<?php

declare(strict_types=1);

namespace App\Models;

use App\Support\Ids\HasPrefixedId;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string|null $campaign_id
 * @property string $code
 * @property string $discount_type
 * @property int $discount_value
 * @property string|null $currency
 * @property int|null $min_order_amount
 * @property int|null $max_discount_amount
 * @property int|null $usage_limit
 * @property int $per_user_limit
 * @property int $times_used
 * @property Carbon|null $starts_at
 * @property Carbon|null $ends_at
 * @property bool $is_active
 * @property string|null $created_by
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class PromoCode extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'prm';

    protected $fillable = [
        'campaign_id', 'code', 'discount_type', 'discount_value', 'currency', 'min_order_amount',
        'max_discount_amount', 'usage_limit', 'per_user_limit', 'times_used', 'starts_at', 'ends_at', 'is_active',
        'created_by',
    ];

    protected function casts(): array
    {
        return [
            'starts_at' => 'datetime',
            'ends_at' => 'datetime',
            'is_active' => 'boolean',
        ];
    }

    /** @return BelongsTo<Campaign, $this> */
    public function campaign(): BelongsTo
    {
        return $this->belongsTo(Campaign::class);
    }
}
